+/// Whether `host` is a domain name (dot-separated letter-digit-hyphen labels),
+/// optionally followed by `:port`, and not an IP address.
+fn is_domain_host(host: &str) -> bool {
+    let (name, port) = match host.rsplit_once(':') {
+        Some((name, port)) => (name, Some(port)),
+        None => (host, None),
