  1	//! Status-change webhooks.
  2	//!
  3	//! When a credential's status flips ([`crate::status::revoke_credential`]),
  4	//! [`Notifier::notify`] sends the change to the relying parties that
  5	//! subscribed to the issuing tenant's changes. A subscription is a tenant
  6	//! setting of kind [`WEBHOOK_KIND`] whose value holds the endpoint `url`.
  7	//!
  8	//! Deliveries run concurrently, at most [`MAX_CONCURRENT_DELIVERIES`] at a
  9	//! time, each bounded by [`DELIVERY_TIMEOUT`], and the whole change by
 10	//! [`DISPATCH_BUDGET`]. There are no retries: every subscriber gets exactly
 11	//! one [`DeliveryEvent`] in the [`DeliverySink`], and one that is not
 12	//! delivered, including one not reached before the budget ran out or whose
 13	//! setting has no usable `url`, is recorded as [`Outcome::Failed`].
 14	//!
 15	//! The canary is a platform subscription on the instance's loopback that
 16	//! receives every change, sent after the subscriber lookup through the same
 17	//! transport as the change's subscribers. [`Notifier::canary_healthy`] is the
 18	//! notifier's health check: green only if, for the most recent change, the
 19	//! canary acknowledged and every subscriber was looked up and attempted
 20	//! within the budget. A relying party's own failure is reported in its
 21	//! delivery event, not in the health check. The canary's own delivery events
 22	//! are recorded under [`PLATFORM_TENANT`], not the changed customer.
 23	
 24	use std::sync::atomic::{AtomicBool, Ordering};
 25	use std::sync::{Arc, Mutex};
 26	use std::time::Duration;
 27	
 28	use serde_json::json;
 29	use tokio::task::JoinSet;
 30	use tokio::time::{timeout_at, Instant};
 31	
 32	use crate::settings::{Setting, SettingsStore};
 33	use crate::status::StatusChange;
 34	use crate::webhook::WebhookTransport;
 35	
 36	/// How long one status change may take, lookup and fan-out together. The
 37	/// deployed function is killed at 10 s from the start of its invocation
 38	/// (`timeout_seconds` in the deployment configuration); this leaves room for
 39	/// the invocation's start-up and for recording what was not delivered.
 40	pub const DISPATCH_BUDGET: Duration = Duration::from_secs(7);
 41	
 42	/// How long one delivery may take, connect included (the platform's own
 43	/// connect timeout is 2 s). An endpoint that accepts the connection and never
 44	/// answers is given up on after this.
 45	pub const DELIVERY_TIMEOUT: Duration = Duration::from_secs(3);
 46	
 47	/// Deliveries in flight at once for one change. With [`DELIVERY_TIMEOUT`]
 48	/// inside [`DISPATCH_BUDGET`], two full rounds of non-answering endpoints
 49	/// (32) still leave every subscriber attempted; healthy endpoints go through
 50	/// at 16 per round trip. Across the 20 instances the deployment allows, that
 51	/// is at most 320 connections through the shared NAT gateways.
 52	pub const MAX_CONCURRENT_DELIVERIES: usize = 16;
 53	
 54	/// Setting kind of a webhook subscription.
 55	pub const WEBHOOK_KIND: &str = "webhook";
 56	
 57	/// The tenant platform subscribers' deliveries (the canary's) are recorded
 58	/// under, so they are not counted as the changed customer's.
 59	pub const PLATFORM_TENANT: &str = "platform";
 60	
 61	pub const CANARY_ID: &str = "canary";
 62	/// The canary receiver the platform operates on the instance's loopback,
 63	/// behind the same outbound client as the subscribers' calls.
 64	pub const CANARY_URL: &str = "http://127.0.0.1/webhooks/canary";
 65	
 66	#[derive(Debug, Clone, PartialEq, Eq)]
 67	pub struct Subscription {
 68	    pub id: String,
 69	    pub url: String,
 70	}
 71	
 72	impl Subscription {
 73	    pub fn canary() -> Self {
 74	        Subscription { id: CANARY_ID.to_string(), url: CANARY_URL.to_string() }
 75	    }
 76	
 77	    /// The subscription a webhook setting describes; its id is the part of
 78	    /// the key after `webhook/`.
 79	    pub fn from_setting(setting: &Setting) -> Option<Self> {
 80	        let url = setting.value.get("url")?.as_str()?;
150	impl Notifier {
151	    pub fn new(settings: Arc<SettingsStore>, transport: Arc<dyn WebhookTransport>, sink: Arc<dyn DeliverySink>) -> Self {
152	        Notifier {
153	            settings,
154	            transport,
155	            sink,
156	            platform: vec![Subscription::canary()],
157	            canary_ok: AtomicBool::new(false),
158	        }
159	    }
160	
161	    /// Adds a subscriber to every tenant's changes.
162	    pub fn with_platform_subscriber(mut self, subscription: Subscription) -> Self {
163	        self.platform.push(subscription);
164	        self
165	    }
166	
167	    /// Whether the most recent change was looked up, attempted for every
168	    /// subscriber within the budget, and acknowledged by the canary.
169	    pub fn canary_healthy(&self) -> bool {
170	        self.canary_ok.load(Ordering::SeqCst)
171	    }
172	
173	    /// Sends `change` to every subscriber of the issuing tenant and to the
174	    /// platform subscribers.
175	    pub async fn notify(&self, change: &StatusChange) {
176	        let tenant = change.issuer.as_str();
177	        let deadline = Instant::now() + DISPATCH_BUDGET;
178	
179	        let Ok(subscriptions) = timeout_at(deadline, self.subscriptions(tenant)).await else {
180	            eprintln!("notifier: {tenant}: subscribers for {} not read within {DISPATCH_BUDGET:?}", change.credential_id);
181	            self.canary_ok.store(false, Ordering::SeqCst);
182	            return;
183	        };
184	        let targets: Vec<Subscription> = self.platform.iter().cloned().chain(subscriptions).collect();
185	        let healthy = self.fan_out(tenant, &targets, payload(change).into(), deadline).await;
186	        self.canary_ok.store(healthy, Ordering::SeqCst);
187	    }
188	
189	    /// The tenant's webhook subscriptions, through the `tenant-kind` index. A
190	    /// webhook setting with no usable `url` is recorded as not delivered.
191	    async fn subscriptions(&self, tenant: &str) -> Vec<Subscription> {
192	        let mut subscriptions = Vec::new();
193	        for setting in self.settings.query_kind(tenant, WEBHOOK_KIND).await {
194	            match Subscription::from_setting(&setting) {
195	                Some(subscription) => subscriptions.push(subscription),
196	                None => self.sink.record(DeliveryEvent {
197	                    tenant: tenant.to_string(),
198	                    subscription: subscription_id(&setting).to_string(),
199	                    outcome: Outcome::Failed { reason: "webhook setting has no url".to_string() },
200	                }),
201	            }
202	        }
203	        subscriptions
204	    }
205	
206	    /// Delivers `body` to every target and records one event per target.
207	    /// `true` if every target was attempted before `deadline` and the canary
208	    /// acknowledged.
209	    async fn fan_out(&self, tenant: &str, targets: &[Subscription], body: Arc<[u8]>, deadline: Instant) -> bool {
210	        let mut done = vec![false; targets.len()];
211	        let mut canary_delivered = false;
212	        let mut next = 0;
213	        let mut in_flight = JoinSet::new();
214	        let exhausted = loop {
215	            while in_flight.len() < MAX_CONCURRENT_DELIVERIES && next < targets.len() {
216	                let (transport, url, body, index) = (self.transport.clone(), targets[next].url.clone(), body.clone(), next);
217	                in_flight.spawn(async move { (index, deliver(transport.as_ref(), &url, &body).await) });
218	                next += 1;
219	            }
220	            match timeout_at(deadline, in_flight.join_next()).await {
221	                Ok(Some(Ok((index, outcome)))) => {
222	                    let sub = &targets[index];
223	                    if sub.id == CANARY_ID {
224	                        canary_delivered = matches!(outcome, Outcome::Delivered { .. });
225	                    }
226	                    done[index] = true;
227	                    self.record(self.owner(tenant, index), sub, outcome);
228	                }
229	                Ok(Some(Err(error))) => eprintln!("notifier: {tenant}: delivery task failed: {error}"),
230	                Ok(None) => break false,
231	                Err(_) => break true,
232	            }
233	        };
234	        in_flight.abort_all();
235	
236	        let reason = if exhausted { format!("not delivered within {DISPATCH_BUDGET:?}") } else { "delivery task failed".to_string() };
237	        for (index, (sub, _)) in targets.iter().zip(&done).enumerate().filter(|(_, (_, done))| !**done) {
238	            self.record(self.owner(tenant, index), sub, Outcome::Failed { reason: reason.clone() });
239	        }
240	        canary_delivered && done.iter().all(|d| *d)
241	    }
242	
243	    /// The tenant a delivery to `targets[index]` is recorded under: platform
244	    /// subscribers come first in the targets.
245	    fn owner<'a>(&self, tenant: &'a str, index: usize) -> &'a str {
246	        if index < self.platform.len() {
247	            PLATFORM_TENANT
248	        } else {
249	            tenant
250	        }
251	    }
252	
253	    fn record(&self, tenant: &str, sub: &Subscription, outcome: Outcome) {
254	        self.sink.record(DeliveryEvent { tenant: tenant.to_string(), subscription: sub.id.clone(), outcome });
255	    }
256	}
257	
258	/// POSTs `body` to `url`, giving up after [`DELIVERY_TIMEOUT`].
259	async fn deliver(transport: &dyn WebhookTransport, url: &str, body: &[u8]) -> Outcome {
260	    match tokio::time::timeout(DELIVERY_TIMEOUT, transport.post(url, body)).await {
261	        Ok(Ok(status)) if (200..300).contains(&status) => Outcome::Delivered { status },
262	        Ok(Ok(status)) => Outcome::Failed { reason: format!("HTTP {status}") },
263	        Ok(Err(error)) => Outcome::Failed { reason: error.to_string() },
264	        Err(_) => Outcome::Failed { reason: format!("no response within {DELIVERY_TIMEOUT:?}") },
265	    }
266	}

