 18	/// The wallet's operations: holder key, credential requests, presentations.
 19	class WalletService {
 20	  WalletService({
 21	    required this._issuer,
 22	    CredentialStore? store,
 23	    HolderKey Function()? newKey,
 24	  }) : _store = store ?? CredentialStore(),
 25	       _newKey = newKey ?? HolderKey.generate;
 26	
 27	  final IssuerClient _issuer;
 28	  final CredentialStore _store;
 29	  final HolderKey Function() _newKey;
 30	
 31	  /// The holder key, created on first use.
 32	  HolderKey holderKey() => _store.holderKey ??= _newKey();
 33	
 34	  /// Requests a [credentialType] credential for this holder and keeps it.
 35	  Future<HeldCredential> requestCredential(String credentialType) async {
 36	    final did = holderKey().did;
 37	    final credential = await _issuer.issue(
 38	      holderDid: did,
 39	      credentialType: credentialType,
 40	    );
 41	    if (credential.holderDid != did) {
 42	      throw WalletException(
 43	        'Credential ${credential.id} was issued to ${credential.holderDid}, not $did',
 44	      );
 45	    }
 46	    _store.save(credential);
 47	    return credential;
 48	  }
 49	
 50	  List<HeldCredential> heldCredentials() => _store.all();
 51	
 52	  HeldCredential? credential(String id) => _store.byId(id);
 53	
 54	  /// Builds a presentation of the held credential [credentialId] in answer
 55	  /// to [request], ready to send to the requester.
 56	  ///
 57	  /// The presentation carries the credential unchanged, the disclosures of
 58	  /// exactly the claims the request asks for, and the request's nonce and
 59	  /// domain, and is signed by the holder key (`Ed25519Signature2020` over the
 60	  /// JCS form without the proof). The credential stays in the wallet.
 61	  ///
 62	  /// Throws [WalletException] rather than build a presentation the verifier
 63	  /// will turn down: the credential is not held, not issued to this holder,
 64	  /// expired, or does not carry a requested claim.
 65	  Future<Map<String, dynamic>> createPresentation(
 66	    String credentialId,
 67	    PresentationRequest request,
 68	  ) async {
 69	    final credential = _store.byId(credentialId);
 70	    if (credential == null) {
 71	      throw WalletException('No credential $credentialId in the wallet');
 72	    }
 73	    final key = holderKey();
 74	    if (credential.holderDid != key.did) {
 75	      throw WalletException(
 76	        'Credential $credentialId was issued to ${credential.holderDid}, not ${key.did}',
 77	      );
 78	    }
 79	    final expiresAt = credential.vc['expires_at'];
 80	    final now = DateTime.now().millisecondsSinceEpoch ~/ 1000;
 81	    if (expiresAt is! int || now > expiresAt) {
 82	      throw WalletException('Credential $credentialId has expired');
 83	    }
 84	
 85	    final disclosures = [
 86	      for (final name in _requestedClaims(request))
 87	        credential.disclosures
 88	            .firstWhere(
 89	              (d) => d.name == name,
 90	              orElse: () => throw WalletException(
 91	                'Credential $credentialId carries no claim $name',
 92	              ),
 93	            )
 94	            .toJson(),
 95	    ];
 96	    final presentation = <String, dynamic>{
 97	      '@context': ['https://www.w3.org/2018/credentials/v1'],
 98	      'type': ['VerifiablePresentation'],
 99	      'holder': key.did,
100	      'verifiableCredential': credential.vc,
101	      'disclosures': disclosures,
102	      'nonce': request.nonce,
103	      'domain': request.domain,
104	    };
105	    final signature = await key.sign(
106	      utf8.encode(JcsUtil.canonicalize(presentation)),
107	    );
108	    presentation['proof'] = {
109	      'type': 'Ed25519Signature2020',
110	      'created': now,
111	      'verificationMethod': key.keyId,
112	      'proofPurpose': 'authentication',
113	      'proofValue': toMultiBase(signature),
114	    };
115	    return presentation;
116	  }
117	
118	  /// The claim names [request] asks for, from `credentialSubject.<name>`
119	  /// paths of its single credential query. No claims means none.
120	  static List<String> _requestedClaims(PresentationRequest request) {
121	    final queries = request.dcqlQuery.credentials;
122	    if (queries.length != 1) {
123	      throw WalletException(
124	        'Request asks for ${queries.length} credentials; one is supported',
125	      );
126	    }
127	    final query = queries.single;
128	    if (query.claimSets != null) {
129	      throw const WalletException('Requests with claim_sets are not supported');
130	    }
131	    final names = <String>[];
132	    for (final claim in query.claims ?? const []) {
133	      final path = claim.path;
134	      if (path.length != 2 ||
135	          path[0] != 'credentialSubject' ||
136	          path[1] is! String) {
137	        throw WalletException('Unsupported claim path $path');
138	      }
139	      if (!names.contains(path[1])) names.add(path[1] as String);
140	    }
141	    return names;
142	  }
143	}

